Q: Angular Input value doesn&#39;t change A: <p>The issue is a classic case where the state of the DOM (what the user types in an <code>&lt;input&gt;</code> field) gets out of sync with your Angular component's state.</p>
<p>When you use <code>value=&quot;{{ some.value }}&quot;</code>, you are setting the <code>value</code> <em>attribute</em> of the input element. This works fine for the initial display. However, once a user types into the input, they are changing the input's <code>value</code> property. At this point, the DOM's state is &quot;owned&quot; by the user's interaction, and Angular's one-way binding via the attribute is no longer strong enough to override it when you select a new item.</p>
<p>To handle this, establish a true two-way data binding. You need to refactor your <code>Detail3Component</code> to react to changes on its <code>@Input</code> and use <code>[(ngModel)]</code> to bind the form fields.</p>
<ol>
<li>Import <code>FormsModule</code></li>
</ol>
<p><code>app.module.ts</code></p>
<pre><code>import { NgModule } from '@angular/core';
import { BrowserModule } from '@angular/platform-browser';
import { FormsModule } from '@angular/forms'; // &lt;-- Import FormsModule

import { AppComponent } from './app.component';
// ... 

@NgModule({
  declarations: [
    AppComponent,
    // ... 
  ],
  imports: [
    BrowserModule,
    FormsModule 
  ],
  providers: [],
  bootstrap: [AppComponent]
})
export class AppModule { }
</code></pre>
<ol start="2">
<li>Update <code>detail3.component.ts</code></li>
</ol>
<pre><code>import { Component, Input, Output, EventEmitter, OnChanges, SimpleChanges } from '@angular/core';
import { Offer } from '../models/offer';
import { OffersService } from '../services/offers.service';
import { AuctionStatus } from '../models/auctionStatus';

@Component({
  selector: 'app-detail3',
  templateUrl: './detail3.component.html',
  styleUrls: ['./detail3.component.css']
})
export class Detail3Component implements OnChanges {

  @Input() editedOfferId: number = -1;
  @Output() editedOfferChanged = new EventEmitter&lt;number&gt;();

  public selectedOffer: Offer | null = null;

  status = AuctionStatus;
  keys: Array&lt;number&gt;;

  constructor(public service: OffersService) {
    this.keys = Object.keys(this.status).filter(k =&gt; !isNaN(Number(k))).map(Number);
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes.editedOfferId &amp;&amp; this.editedOfferId !== -1) {
      const foundOffer = this.service.findById(this.editedOfferId);
      if (foundOffer) {
        this.selectedOffer = { ...foundOffer };
      } else {
        this.selectedOffer = null;
      }
    } else if (this.editedOfferId === -1) {
      this.selectedOffer = null;
    }
  }

  checkObjectChanged(): void {
    console.log('Object changed:', this.selectedOffer);
  }
}
</code></pre>
<ol start="3">
<li>Update <code>detail3.component.html</code></li>
</ol>
<pre><code>&lt;div id=&quot;content&quot; *ngIf=&quot;selectedOffer&quot;&gt;
  &lt;div id=&quot;data-table&quot;&gt;
    &lt;table&gt;
      &lt;tr&gt;
        &lt;th scope=&quot;row&quot; colspan=&quot;2&quot;&gt;Selected offer details(id = {{selectedOffer.id}})&lt;/th&gt;
      &lt;/tr&gt;
      &lt;tr&gt;
        &lt;th scope=&quot;row&quot;&gt;Title:&lt;/th&gt;
        &lt;td&gt;&lt;input type=&quot;text&quot; id=&quot;txtTitle&quot; [(ngModel)]=&quot;selectedOffer.title&quot; (input)=&quot;checkObjectChanged()&quot;&gt;&lt;/td&gt;
      &lt;/tr&gt;
      &lt;tr&gt;
        &lt;th scope=&quot;row&quot;&gt;Description:&lt;/th&gt;
        &lt;td&gt;&lt;input type=&quot;text&quot; id=&quot;txtDescription&quot; [(ngModel)]=&quot;selectedOffer.description&quot; (input)=&quot;checkObjectChanged()&quot;&gt;&lt;/td&gt;
      &lt;/tr&gt;
      &lt;tr&gt;
        &lt;th scope=&quot;row&quot;&gt;Status:&lt;/th&gt;
        &lt;td&gt;
          &lt;select id=&quot;txtStatus&quot; [(ngModel)]=&quot;selectedOffer.auctionStatus&quot; (change)=&quot;checkObjectChanged()&quot;&gt;
            &lt;option *ngFor=&quot;let key of keys&quot; [ngValue]=&quot;key&quot;&gt;{{status[key]}}&lt;/option&gt;
          &lt;/select&gt;
        &lt;/td&gt;
      &lt;/tr&gt;
      &lt;tr&gt;
        &lt;th scope=&quot;row&quot;&gt;Highest Bid:&lt;/th&gt;
        &lt;td&gt;&lt;input type=&quot;number&quot; id=&quot;txtHighestBid&quot; [(ngModel)]=&quot;selectedOffer.valueHighestBid&quot; (input)=&quot;checkObjectChanged()&quot;&gt;&lt;/td&gt;
      &lt;/tr&gt;
    &lt;/table&gt;
  &lt;/div&gt;
&lt;/div&gt;

&lt;div *ngIf=&quot;!selectedOffer&quot;&gt;
  &lt;label id=&quot;lblNothingSelected&quot;&gt;Nothing has been selected yet&lt;/label&gt;
&lt;/div&gt;
</code></pre>

Q: Injecting the current request in a service from an other service doesn&#39;t work A: <p>I think you need to try using a Custom provider that has a REQUEST injected into it.</p>
<p>Example of custom provider:</p>
<pre><code>import { REQUEST } from '@nestjs/core';
import type { Request } from 'express';

import { CustomerContext } from '../../context/context.interface';

export const exampleProvider = {
  inject: [REQUEST],
  provide: 'EXAMPLE_PROVIDER_TOKEN',
  useFactory: (req: Request) =&gt; {
    return req;
  },
};
</code></pre>
<p>How module that exports this provider needs to look like</p>
<pre><code>@Module({
  exports: [exampleProvider],
  providers: [exampleProvider],
})
export class ExampleModule {}
</code></pre>
<p>And this is how you use it</p>
<pre><code>import { Injectable, Scope, Inject } from '@nestjs/common';
import type { Request } from 'express';

@Injectable({ scope: Scope.REQUEST })
export class CatsService {
  constructor(@Inject('EXAMPLE_PROVIDER_TOKEN') private readonly request: Request) {}
}
</code></pre>

Q: Export HTML table data to Excel using JavaScript / jQuery is not working properly in Chrome browser A: <p>The below code will work on the latest Chrome, Edge, and Firefox and does not require a third-party library.</p>
<p><strong>HTML</strong></p>
<pre><code>&lt;button onclick=&quot;download_table_as_csv('MyTableID_Value');&quot;&gt;Export as CSV&lt;/button&gt;
</code></pre>
<p><strong>Jscript</strong></p>
<pre><code>function download_table_as_csv(table_id, separator = ',') {

    // Select rows from table_id
    var rows = document.querySelectorAll('table#' + table_id + ' tr');

    // Construct csv
    var csv = [];
    for (var i = 0; i &lt; rows.length; i++) {
        var row = [], cols = rows[i].querySelectorAll('td, th');
        for (var j = 0; j &lt; cols.length; j++) {
            // Clean innertext to remove multiple spaces and jumpline (break csv)
            var data = cols[j].innerText.replace(/(\r\n|\n|\r)/gm, '').replace(/(\s\s)/gm, ' ')
            // Escape double-quote with double-double-quote (see https://stackoverflow.com/questions/17808511/properly-escape-a-double-quote-in-csv)
            data = data.replace(/&quot;/g, '&quot;&quot;');
            // Push escaped string
            row.push('&quot;' + data + '&quot;');
        }
        csv.push(row.join(separator));
    }

    var csv_string = csv.join('\n');

    // Download it
    var filename = 'export_' + table_id + '_' + new Date().toLocaleDateString() + '.csv';
    var link = document.createElement('a');
    link.style.display = 'none';
    link.setAttribute('target', '_blank');
    link.setAttribute('href', 'data:text/csv;charset=utf-8,' + encodeURIComponent(csv_string));
    link.setAttribute('download', filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
}
</code></pre>
